features.push({id:'dynamics_sensors',num:'10',icon:'hydraulic',title:'IMU·압력·좌우 포크 하중',sub:'차체 운동·실린더 압력·접촉력을 센서로 측정',status:'측정 · 센서 제어 연결',body:'물리 스텝에서 차체의 장착점 운동, 실린더 게이지 압력, 좌우 포크와 팔레트의 접촉력을 읽습니다. 센서별 잡음·바이어스·양자화·포화·지연·통신 누락을 적용합니다.',formula:'IMU 비력 = R⁻¹(a − g) · 하중 = 구간 접촉 충격량 / 구간 시간',params:[['IMU / 압력 / 하중 취득','100Hz'],['IMU 범위','±8g · ±500deg/s'],['압력 / 포크 한쪽 범위','0~16MPa / ±20kN'],['지연 / 오래된 값','20ms / 250ms']],limit:'가상 설계로 실센서 보정값이 아닙니다. 포크는 이상적인 계측 패드의 축방향 접촉력이며 실제 변형률/로드핀 회로나 화물 저울은 아닙니다. IMU는 Unreal 축 기준의 원시 비력·각속도로, 융합 자세·위치·SLAM을 출력하지 않습니다. 압력은 승강 제어, IMU는 센서 주행·위치 추정, 좌우 하중은 자동 인양·하역 판정에 연결했습니다. 융합 위치 추정은 별도 주행 항목에서 확인합니다.',source:'DynamicsSensors.cpp · JointSensorSampling.cpp · HydraulicCallback.cpp'});

features.push({id:'proximity_sensors',num:'11',icon:'cargo',title:'포크 근거리·물체 존재',sub:'포크 뿌리·끝 거리와 위쪽 표면 감지',status:'측정 · 센서 제어 연결',body:'좌우 포크 뿌리·끝에서 전방 거리를 측정하고, 각 포크의 두 지점에서 위쪽 물체 존재를 감지합니다. 실제 팔레트 판재와 구멍을 읽으며 포크 승강·휨에 따라 장착점이 움직입니다.',formula:'가장 가까운 실제 표면 → 거리 / 가림 / 반환 없음 · 스위치 ON/OFF',params:[['거리 / 존재 채널','4 / 4개 · 목표 20Hz'],['거리 / 존재 범위','0.02~1.5m / 0~0.15m'],['최소 지연 / 오래된 값','30 / 300ms'],['조작','L 광선 표시 · U 통신 중단/복구']],limit:'가상 단일 광선 모델입니다. 실제 센서 보정·광학 반사 특성은 미구현입니다. 물체 감지가 팔레트 종류나 완전 삽입을 확정하지 않습니다. 거리·존재 측정은 형상·하중과 결합한 삽입 판정 및 자동 작업 정지에 연결했습니다.',source:'ProximitySensors.cpp · ProximitySampling.cpp'});

features.push({id:'sensor_lift_control',num:'12',icon:'hydraulic',title:'센서 기반 포크 높이 제어',sub:'높이·리미트·압력 측정으로 유압 밸브 명령',status:'수동·자동 작업 승강 피드백',body:'Q/E 또는 자동 작업이 정한 목표 높이를 실제 높이 센서로 맞춥니다. 상·하한은 해당 방향을 제한하고, 압력이 높으면 상승을 차단합니다. 센서 사용 불가나 명령 타임아웃은 승강 정지를 유지하고 신호 복구 후 Y 확인을 요구합니다.',formula:'센서 높이 오차 + 적분 − 측정 속도 감쇠 → 유압 밸브',params:[['조작','Q/E 목표 · U 고장 · Y 복구 확인'],['제어 입력','높이·리미트·실린더 압력'],['명령 유효시간','100ms · 물리 스레드 감시'],['복구 시 목표','현재 측정 높이 · 이전 목표 자동 복귀 없음']],limit:'시뮬레이션 인터록으로 안전 등급을 인증하지 않았습니다. 밸브와 적재물은 물리 응답을 따라 감속하므로 정지 명령이 순간 고정을 뜻하지 않습니다. 팔레트 인식·삽입 판정은 별도 자동 작업과 연결했습니다. 등록 구역 경로 주행은 임무 항목에서 확인합니다.',source:'SensorLiftControl.cpp · SensorLiftIntegration.cpp · HydraulicCallback.cpp'});

features.push({id:'lidar_safety',num:'13',icon:'drive',title:'주변 LiDAR·차량 정지와 복구',sub:'두 2D 스캔의 실제 측정점으로 보호 영역 검사',status:'1묶음 · 수동·임무 주행 보호',body:'전후 대각 모서리에서 물리 충돌 형상을 측정합니다. 영역 안 장애물은 주행을 정지하고, 센서 고장이나 X는 승강까지 정지합니다. 정상 신호와 중립·Y 확인 후 복구하며 웹은 실제 스캔과 상태를 표시합니다.',formula:'측정 거리 + 장착점 → 보호 영역 점 → 정지 래치 / 명시적 복구',params:[['측정','2 × 270 rays · 10Hz · 0.05~8m'],['전달 지연 / 오래된 값','50 / 350ms'],['조작','X 전체 정지 · Y 확인 · I 광선 · U 단절'],['수동 작업','Shift 유지 · 목표 0.15m/s · 고장 우회 불가']],limit:'고정 높이의 가상 측정 모델입니다. 수동 주행은 전체 고정 여유, 허가된 임무 주행은 전체 외곽과 명령 방향 정지 여유를 사용합니다. 경로 계획과 측정 위치 추정은 별도 항목입니다. 안전 인증이나 모든 노면 정지거리 보장이 아닙니다. Shift는 장애물 주행 정지를 일시 해제하므로 주변을 확인하며 수동 조작합니다.',source:'LidarSafety.cpp · LidarSafetySampling.cpp · VehicleGuardLab.cpp'});

features.push({id:'sensor_drive',num:'14',icon:'drive',title:'센서 주행·2D 위치 추정',sub:'엔코더·IMU 제어와 고정 지도 LiDAR 보정',status:'2번 묶음 · 수동·임무 주행 피드백',body:'네 바퀴 엔코더로 토크를 제어하고 정지 상태에서 바이어스를 추정한 IMU로 방향을 유지합니다. 지연된 LiDAR를 취득 시각의 오도메트리와 정합해 지도 위치를 보정합니다. 주행 센서 단절·명령 만료는 전체 정지와 Y 복구에 연결합니다.',formula:'측정 회전량·각속도 → 오도메트리 → 고정 지도 정합 / 측정 속도 오차 → 토크',params:[['시작','이동 입력을 놓고 정지 바이어스 추정'],['센서','엔코더 4개·IMU 100Hz / 기존 오차·지연 유지'],['위치','평면 오도메트리 + 고정 지도 LiDAR 정합'],['내보내기','실제 수신 주행·위치 CSV 26열']],limit:'출발 구역의 위치·방향과 미리 작성한 정적 지도를 안다고 가정합니다. 헛도는 바퀴 속도는 실제 지면 속도와 다릅니다. 지도 작성·전역 재위치 추정·3D SLAM은 후속 범위입니다. 등록 구역 경로 주행은 임무 항목에 연결했습니다. 실차 정확도·안전 인증이 아닙니다.',source:'SensorDriveModel.cpp · SensorDriveIntegration.cpp · PlanarLocalization.cpp'});

features.push({id:'pallet_perception',num:'15',icon:'cargo',title:'팔레트 인식·삽입 판정',sub:'실제 깊이 영상의 통로 검사와 센서 융합',status:'3번 묶음 · 자동 작업에 연결',body:'현재 Warehouse 팔레트 계열의 앞면과 두 통로를 측정 깊이에서 찾습니다. 양쪽 뿌리 거리·네 존재 센서·접촉 하중·높이를 결합해 정렬·부분/완전 삽입 증거와 지지를 구분합니다. 전방 화면의 초록 통로 표시와 웹 판정·CSV를 제공합니다.',formula:'깊이 형상 증거 + 치수 사전 정보 → 앞면·통로 / 깊이 여유 + 존재·하중 → 판정',params:[['인식 입력','오차·지연·결측이 있는 실제 전방 깊이'],['새 전방 배치','캐리지 (5,-10,10)cm · 아래로 10°'],['완전 삽입','좌우 깊이 − 여유 ≥ 1.02m · 네 존재 ON · 지속 확인'],['내보내기','실제 수신 팔레트·삽입 CSV 29열']],limit:'범용 학습 검출기가 아닌 알려진 팔레트 계열 모델입니다. 통로 높이·간격은 치수 사전 정보를 사용합니다. 가림 추적은 20초·1.8m로 제한하며 여유는 가정값입니다. 하중 지지는 현재 완전 삽입을 보증하지 않습니다. 자동 정렬·삽입 제어는 별도 자동 작업 항목에 연결했습니다.',source:'PalletVision.cpp · PalletPerception.cpp · CameraSensors.cpp'});

features.push({id:'handling_control',num:'16',icon:'cargo',title:'자동 정렬·삽입·인양·하역',sub:'측정 인식에서 유압·구동 제어까지 연결',status:'4번 묶음 · 로컬 작업',body:'측정한 팔레트 통로로 정렬·삽입하고 완전 삽입 증거를 확인한 뒤 인양·후퇴합니다. 등록된 랙 1/2단은 하중 전달을 확인한 뒤 포크를 빼며, 카메라·센서 이상이나 작업 취소는 정지를 잠급니다.',formula:'측정 인식·센서 → 작업 단계 → 저속 주행 / 유압 목표 → 전달 확인',params:[['기본 실행','Start.bat → Play'],['조작','5 바닥 인양 / 6·7 랙 인양 / 8·9 랙 하역 / 0 취소'],['작업 속도','전후 ≤ 0.12m/s / 횡 ≤ 0.06m/s / 회전 ≤ 0.08rad/s'],['웹','실제 작업 단계·정지 사유·명령 / CSV 20열']],limit:'가까운 작업 구역의 알려진 팔레트 계열과 등록된 랙을 대상으로 합니다. 공간적인 대상 허용은 같은 공간의 다른 물체를 완전히 구분하지 못합니다. 등록 구역 경로 주행은 임무 항목에 연결했습니다. 인증된 안전 제어·실차 검증을 뜻하지 않습니다.',source:'HandlingModel.cpp · HandlingControl.cpp · PalletPerception.cpp · LidarSafetySampling.cpp'});

features.push({id:'mission',num:'17',icon:'drive',title:'경로 주행·운반 임무',sub:'등록 지도와 측정 위치로 인양→운반→랙 하역 연결',status:'5번 묶음 · 제한된 알려진 작업 구역',body:'전체 차체·포크 외곽을 고려한 2D 격자 경로를 계획하고 실제 LiDAR 점으로 재계획합니다. 측정 위치·속도로 메카넘 주행을 제어하며 로컬 작업의 새 완료 기록을 확인한 뒤 다음 단계로 넘어갑니다. 고장·차단·수동 개입은 정지하고 명시적으로 재개합니다.',formula:'측정 위치·LiDAR → 경로 → 구동 토크 / 작업 완료 기록 → 다음 임무 단계',params:[['시작','Start.bat → Play → PageDown/Up 층 선택 → Enter'],['중단·복구','Backspace 일시정지 / ] 재개 / 0 취소 / X 비상 / Y 확인'],['주행 상한','무적재 0.25m/s · 적재 0.18m/s · 고정 방향'],['웹','실제 임무 단계·경로·추정 위치 / 수신 CSV 30열']],limit:'등록 출발 구역·2D 지도·팔레트 계열·랙 좌표와 평지 저속 조건을 사용합니다. SLAM·전역 재위치 추정·움직이는 사람의 안전 보장이나 모든 창고 형상 운행이 아닙니다. 삽입·하중 전달 중 중단은 수동 점검과 복구가 필요합니다.',source:'MissionPlanner.cpp · MissionModel.cpp · MissionControl.cpp'});
